    /// [`Node::save_file`], which streams to disk.
    pub fn read_file(&self, file_conv: ConversationId) -> Result<Vec<u8>, NodeError> {
        self.reject_protected_file(file_conv)?;
        self.read_file_internal(file_conv)
    }

