    pub fn file_ready_to_save(&self, file_conv: ConversationId) -> Result<bool, NodeError> {
        if self.file_is_protected(file_conv)? {
            return Ok(false);
        }
        let Some(progress) = self.file_progress(file_conv)? else {
            return Ok(false);
        };
        if progress.done == progress.total {
            return Ok(true);
        }
        let manifest = self
            .files
