    async fn run_accept_loop_inner(
        self: Arc<Self>,
        listener: TcpListener,
        #[cfg(test)] account_periodic_repair: bool,
    ) {
        #[cfg(test)]
        let account_history = {
            let node = Arc::clone(&self);
            async move {
                if account_periodic_repair {
                    Box::pin(node.run_account_history_loop()).await;
                } else {
                    Box::pin(node.run_account_history_loop_with_tick(None)).await;
                }
            }
        };
        #[cfg(not(test))]
        let account_history = Arc::clone(&self).run_account_history_loop();
        let changes = self
            .roster
            .lock()
            .expect("roster mutex not poisoned")
            .changes();
        // select! branches share one task. A synchronous maintenance turn must
        // not prevent an available host worker from accepting a new connection.
        // The parent owns cancellation; the actual child owns its retirement
        // permit through destruction of its listener and captured Node.
        let Some(accept_work) = self.runtime_work.admit() else {
            return;
        };
        let mut inbound = tokio::task::JoinSet::new();
        inbound.spawn(accept_work.track(Arc::clone(&self).accept_connections(listener)));
        tokio::select! {
            _ = Arc::clone(&self).run_profile_compaction_loop() => {}
            _ = Arc::clone(&self).run_delivery_loop() => {}
            _ = Arc::clone(&self).run_channel_control_retry_loop() => {}
            _ = Arc::clone(&self).run_channel_recovery_loop(changes) => {}
            _ = account_history => {}
            _ = Arc::clone(&self).run_account_wake_loop() => {}
            _ = Arc::clone(&self).run_expiry_loop() => {}
            result = inbound.join_next() => {
                if let Some(Err(error)) = result {
                    if error.is_panic() {
                        std::panic::resume_unwind(error.into_panic());
                    }
                    log::warn!("inbound listener task cancelled: {error}");
                }
            }
        }
        // Preserve completed-parent retirement too. Cancellation of this parent
        // drops the JoinSet; runtime_work retains the child's actual lifetime.
        inbound.shutdown().await;
    }

    async fn run_expiry_loop(self: Arc<Self>) {
        loop {
            tokio::time::sleep(Duration::from_secs(1)).await;
            let Some(work) = self.runtime_work.admit() else {
                return;
            };
            let node = Arc::clone(&self);
            match work
                .spawn_blocking(move || {
                    #[cfg(test)]
                    if let Some(hook) = node.expiry_cleanup_hook.lock().unwrap().take() {
                        hook();
                    }
                    node.prune_expired_received()
                })
                .await
                .map(|value| value.into_inner())
            {
                Ok(Ok(_)) => {}
                Ok(Err(error)) => log::warn!("message expiry cleanup failed: {error}"),
                Err(error) => log::warn!("message expiry task failed: {error}"),
            }
        }
    }

    fn selected_file(&self, file: ConversationId) -> std::io::Result<Option<(PathBuf, bool)>> {
        if let Some(index) = &self.index {
            let mut after = None;
            loop {
                let page = index.exact(file, after.as_deref())?;
                if page.is_empty() {
                    return Ok(None);
                }
                for entry in &page {
                    after = Some(entry.name.clone());
                    if entry.partial {
                        continue;
                    }
                    let path = self.dir.join(&entry.name);
                    match std::fs::symlink_metadata(&path) {
                        Ok(metadata) if metadata.is_file() => {
                            return Ok(Some((path, entry.legacy)));
                        }
                        Ok(_) => {}
                        Err(error) if error.kind() == std::io::ErrorKind::NotFound => {}
                        Err(error) => return Err(error),
                    }
                }
                if page.len() < 32 {
                    return Ok(None);
                }
            }
        }
        let hex = hex::encode(file.as_bytes());
        for entry in std::fs::read_dir(&self.dir)? {
            #[cfg(test)]
