    let recipient_proof = Announce::new_with_account(&recipient_identity, &recipient_account, "Recipient", recipient_listener.local_addr().unwrap().port());
    let (sender, _) = node(sender_dir.path(), sender_identity, sender_account, &recipient_proof);
    let (recipient, _) = node(recipient_dir.path(), recipient_identity, recipient_account, &sender_proof);
    let id = sender.enqueue_to_account(&recipient.account_id(), b"one accepted DM survives first transport failure", None).await.unwrap();
    let destination = sender.delivery.lock().unwrap().message(id).unwrap().destinations[0].clone();
    assert_eq!(destination.event.id, id);
