    // before closing, so an unrelated dial failure cannot satisfy the control.
    // Borrowed futures retain cancellation ownership without a detached server.
    let (held, recipient_listener) = tokio::time::timeout(Duration::from_secs(5), async {
        tokio::join!(
            sender.transfer_delivery_destination(&peer, &destination, destination.event.conversation_id),
            async {
                let (mut stream, _) = recipient_listener.accept().await.unwrap();
                stream.read_exact(&mut [0u8; 1]).await.unwrap();
                drop(stream);
                recipient_listener
            }
        )
    }).await.expect("the exact fresh handshake must fail within the existing observation budget");
    assert!(!held, "closing before authentication must not acknowledge the DM");
    assert_eq!(sender.delivery_status(id), Some(super::delivery_store::DeliveryStatus::Awaiting));
    assert!(recipient.account_history(&sender.account_id(), 10).unwrap().is_empty());

