        for peer in &mut peers { peer.launch(); }
        // No resend or manual flush: the application owns durable recovery.
        tokio::time::timeout(Duration::from_secs(5), async {
            loop {
                let history = recipient.account_history(&sender.account_id(), 10).unwrap();
                if history.iter().any(|entry| entry.id == id) {
                    assert_eq!(history.len(), 1);
                    assert_eq!(history[0].text, b"one accepted DM survives first transport failure");
                    break;
                }
                tokio::time::sleep(Duration::from_millis(10)).await;
            }
        }).await.expect("the real hosts must recover the same accepted DM without resending");
    }).catch_unwind().await;
    let mut cleanup_failure = None;
    for peer in peers {
        let stopped = std::panic::AssertUnwindSafe(peer.stop()).catch_unwind().await;
        if cleanup_failure.is_none() { cleanup_failure = stopped.err(); }
    }
    if let Err(error) = outcome { std::panic::resume_unwind(error); }
    if let Some(error) = cleanup_failure { std::panic::resume_unwind(error); }
}

