      "utf8",
    );
    const pins = [...source.matchAll(/cargo-nextest@([0-9.]+)/gu)].map(
      (match) => match[1],
    );
    assert(pins.length > 0, `${file} must install the owned nextest version`);
    assert(
      pins.every((pin) => pin === versions.nextest),
      `${file} nextest installer drift`,
    );
