# typos (crate-ci) — source spell checker config.
# https://github.com/crate-ci/typos

[default.extend-words]
# "pn" / "PN" is the Double Ratchet "previous sending chain length" variable
# (Signal Double Ratchet spec), used throughout src-tauri/src/ratchet and its docs.
pn = "pn"
# "abd" is a test byte-string literal (file_checksum(b"abc") vs b"abd")).
abd = "abd"
# "seeked" is the HTMLMediaElement DOM event name (video poster capture in mediaFile.tsx);
# typos wants "sought", but it's a Web API identifier, not prose.
seeked = "seeked"
# The city-photo credit names the photographer's site, foto-tw.de.
foto = "foto"
# Spanish client-relative presence wording is asserted outside the locale catalogs.
cliente = "cliente"

[default.extend-identifiers]
# "UPnP" (Universal Plug and Play) trips the Pn->On heuristic.
UPnP = "UPnP"
# PNG filter 4 uses the Paeth predictor (a proper algorithm name).
paeth = "paeth"

[type.swift.extend-identifiers]
# CoreBluetooth's CBAttributePermissions.writeable is the SDK's API spelling.
writeable = "writeable"

[type.changelog]
extend-glob = ["CHANGELOG.md"]
# Release-please commit-link labels are identifiers, not English words.
extend-ignore-re = ['\[[0-9a-f]{7,40}\]\(https://github\.com/[^/\s]+/[^/\s]+/commit/[0-9a-f]{40}\)']

[files]
extend-exclude = [
  "Cargo.lock",
  "frontend/package-lock.json",
  "package-lock.json",
  "src-tauri/icons/**",
  "specifications/**/*.md",
  # UI translation catalogs contain deliberately non-English text.
  # so the English spell-checker would flag every localized word (foto, contactos, tema…).
  "frontend/src/locales/**",
  "site/locales/**",
  # Generated coverage artifacts (function-name fragments trip the checker).
  "**/lcov.info",
  "**/*.info",
  "**/coverage/**",
]
"}

